CREATE POLICY "Facility request edits stay in editor hub" ON public.ops_tasks AS RESTRICTIVE FOR UPDATE TO authenticated USING (task_mode <> 'facility_request' OR public.can_edit_facility(CASE hub WHEN 'provence' THEN 'fr' WHEN 'czech' THEN 'cz' WHEN 'tuscany' THEN 'it' WHEN 'croatia' THEN 'hr' ELSE '' END)) WITH CHECK (task_mode <> 'facility_request' OR (public.can_edit_facility(CASE hub WHEN 'provence' THEN 'fr' WHEN 'czech' THEN 'cz' WHEN 'tuscany' THEN 'it' WHEN 'croatia' THEN 'hr' ELSE '' END) AND (project_id IS NULL OR EXISTS (SELECT 1 FROM public.facility_projects p WHERE p.id = project_id AND p.hub = CASE hub WHEN 'provence' THEN 'fr' WHEN 'czech' THEN 'cz' WHEN 'tuscany' THEN 'it' WHEN 'croatia' THEN 'hr' ELSE '' END))));